import json, subprocess, sys

def first(need):
    r = subprocess.run([sys.executable, '_tools/kbtools.py', need, '--json'], capture_output=True, text=True)
    try:
        return json.loads(r.stdout)['entries'][0]['tool']
    except (ValueError, KeyError, IndexError, TypeError):
        return None

cases = {'query log': 'querylog.py', 'how long landing steps take': 'backlog.py'}
got = {need: first(need) for need in cases}
print('first entry for each need:', got, '| wanted:', cases)
sys.exit(0 if got == cases else 1)

